/* ---------- standalone dsh_kline chart API ---------- */
function sanitizeToolArguments(args = {}) {
  if (!args || typeof args !== "object") return {};
  return Object.fromEntries(Object.entries(args).filter(([, value]) => value !== undefined));
}
async function callTool(name, args) {
  const toolArgs = sanitizeToolArguments(args);
  // Interactive chart actions go through the plugin's authenticated loopback
  // proxy. `/api/tools` belongs to the DSH host, while `/dsh-kline/api/tools`
  // carries the active chart-service token and works for standalone workspaces.
  const response = await fetch(`/dsh-kline/api/tools/${encodeURIComponent(name)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(toolArgs),
  });
  const result = await response.json();
  if (!response.ok) throw new Error(result?.message || result?.error || `HTTP ${response.status}`);
  return result;
}
function sleep(ms) { return new Promise((resolve) => window.setTimeout(resolve, ms)); }
function isRetryableToolError(error) {
  const message = String(error?.message || error || "").toLowerCase();
  return /(timeout|timed out|network|temporar|429|503|fetch_failed|stock_candlesticks)/.test(message);
}
async function callMarketTool(name, args, attempts = 2) {
  let lastError = null;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      const result = await callTool(name, args);
      const structured = result?.structuredContent || result || {};
      if (result?.isError || structured.ok === false) {
        throw new Error(structured.message || structured.error || `${name} failed`);
      }
      return result;
    } catch (error) {
      lastError = error;
      if (attempt + 1 >= attempts || !isRetryableToolError(error)) break;
      await sleep(420 * (attempt + 1));
    }
  }
  throw lastError || new Error(`${name} failed`);
}

