function initCanvasResizer() {
  const handle = document.getElementById("canvasResizer");
  if (!handle) return;
  let activePointerId = null;
  let startY = 0;
  let startHeight = 0;
  const applyHeight = (height) => {
    canvasBaseHeightOverride = Math.round(Math.min(CANVAS_BASE_MAX_HEIGHT, Math.max(CANVAS_BASE_MIN_HEIGHT, height)));
    recalcChartHeight();
    saveWorkspacePreferences();
  };
  const resetHeight = () => {
    canvasBaseHeightOverride = null;
    recalcChartHeight();
    saveWorkspacePreferences();
  };
  document.getElementById("canvasAutoHeightBtn")?.addEventListener("click", resetHeight);
  handle.addEventListener("dblclick", resetHeight);
  syncCanvasHeightControls();
  const stop = (event) => {
    if (event.pointerId !== activePointerId) return;
    handle.classList.remove("dragging");
    if (handle.hasPointerCapture(event.pointerId)) {
      try { handle.releasePointerCapture(event.pointerId); } catch {}
    }
    activePointerId = null;
  };
  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    event.preventDefault();
    activePointerId = event.pointerId;
    startY = event.clientY;
    const paneCount = [volVisible, macdVisible, kdjVisible, rsiVisible, atrVisible].filter(Boolean).length;
    startHeight = chartBaseHeight() + paneCount * PANE_SHRINK_STEP;
    handle.classList.add("dragging");
    try { handle.setPointerCapture(event.pointerId); } catch {}
  });
  handle.addEventListener("pointermove", (event) => {
    if (event.pointerId !== activePointerId) return;
    applyHeight(startHeight + event.clientY - startY);
  });
  handle.addEventListener("pointerup", stop);
  handle.addEventListener("pointercancel", stop);
  handle.addEventListener("lostpointercapture", () => {
    handle.classList.remove("dragging");
    activePointerId = null;
  });
  handle.addEventListener("keydown", (event) => {
    const paneCount = [volVisible, macdVisible, kdjVisible, rsiVisible, atrVisible].filter(Boolean).length;
    const current = chartBaseHeight() + paneCount * PANE_SHRINK_STEP;
    if (event.key === "Escape") resetHeight();
    else if (event.key === "ArrowUp") applyHeight(current - 24);
    else if (event.key === "ArrowDown") applyHeight(current + 24);
    else if (event.key === "Home") applyHeight(CANVAS_BASE_MIN_HEIGHT);
    else if (event.key === "End") applyHeight(CANVAS_BASE_MAX_HEIGHT);
    else return;
    event.preventDefault();
  });
}

function syncCanvasHeightControls() {
  const button = document.getElementById("canvasAutoHeightBtn");
  if (!button) return;
  const automatic = canvasBaseHeightOverride === null;
  const english = viewLanguage === "en";
  button.textContent = english ? "Reset auto height" : "恢复自适应";
  button.disabled = automatic;
  document.getElementById("canvasHeightLabel").textContent = english ? "Chart height" : "图表高度";
  document.getElementById("canvasHeightStatus").textContent = english ? (automatic ? "Fit to window" : "Manually adjusted") : (automatic ? "自适应窗口" : "手动调整");
  const hint = english ? "Drag the handle below the chart to resize; double-click to fit the window." : "拖动图表底部横条可调整高度，双击横条可恢复自适应。";
  document.getElementById("canvasHeightHint").textContent = hint;
  document.getElementById("canvasResizer")?.setAttribute("title", hint);
}

