function comparisonRowsForTime(rows, time, indexState) {
  while (indexState.index + 1 < rows.length && Number(rows[indexState.index + 1]?.time) <= time) indexState.index += 1;
  return Number(rows[indexState.index]?.time) <= time ? rows[indexState.index] : null;
}
function comparisonPairs(rows) {
  const cursor = { index: 0 };
  const pairs = [];
  for (const candle of currentCandles) {
    const comparable = comparisonRowsForTime(rows, Number(candle.time), cursor);
    const primaryClose = Number(candle.close);
    const compareClose = Number(comparable?.close);
    if (Number.isFinite(primaryClose) && primaryClose > 0 && Number.isFinite(compareClose) && compareClose > 0) {
      pairs.push({ time: Number(candle.time), primary: primaryClose, compare: compareClose });
    }
  }
  return pairs;
}
function pearsonCorrelation(left, right) {
  if (left.length < 2 || left.length !== right.length) return null;
  const leftMean = left.reduce((sum, value) => sum + value, 0) / left.length;
  const rightMean = right.reduce((sum, value) => sum + value, 0) / right.length;
  let numerator = 0, leftSquares = 0, rightSquares = 0;
  for (let index = 0; index < left.length; index += 1) {
    const a = left[index] - leftMean, b = right[index] - rightMean;
    numerator += a * b;
    leftSquares += a * a;
    rightSquares += b * b;
  }
  const denominator = Math.sqrt(leftSquares * rightSquares);
  return denominator > 0 ? numerator / denominator : null;
}
function comparisonMetrics(rows) {
  const pairs = comparisonPairs(rows);
  if (pairs.length < 2) return null;
  const first = pairs[0], last = pairs[pairs.length - 1];
  const primaryReturn = (last.primary / first.primary - 1) * 100;
  const compareReturn = (last.compare / first.compare - 1) * 100;
  const primaryDaily = [], compareDaily = [];
  for (let index = 1; index < pairs.length; index += 1) {
    primaryDaily.push(pairs[index].primary / pairs[index - 1].primary - 1);
    compareDaily.push(pairs[index].compare / pairs[index - 1].compare - 1);
  }
  return {
    pairs,
    primaryReturn,
    compareReturn,
    excessReturn: primaryReturn - compareReturn,
    relativeStrength: ((1 + primaryReturn / 100) / (1 + compareReturn / 100) - 1) * 100,
    correlation: pearsonCorrelation(primaryDaily, compareDaily),
    lastPrice: last.compare,
  };
}
