function drawComparisonLayer() {
  const layer = document.getElementById("comparisonLayer");
  const panel = document.getElementById("comparisonPerformance");
  const chart = document.getElementById("comparisonPerformanceSvg");
  const title = document.getElementById("comparisonPerformanceTitle");
  const subtitle = document.getElementById("comparisonPerformanceSubtitle");
  const legend = document.getElementById("comparisonPerformanceLegend");
  if (layer) layer.innerHTML = "";
  if (!panel || !chart || !title || !legend) return;
  if (currentCandles.length < 2 || !comparisonSeries.length) { panel.hidden = true; legend.innerHTML = ""; chart.innerHTML = ""; return; }
  const valid = comparisonSeries.map((series, index) => {
    const rows = Array.isArray(series.rows) ? series.rows.filter((row) => Number.isFinite(Number(row?.time)) && Number.isFinite(Number(row?.close))) : [];
    const metrics = comparisonMetrics(rows);
    return metrics ? { series, metrics, color: COMPARISON_COLORS[index % COMPARISON_COLORS.length] } : null;
  }).filter(Boolean);
  if (!valid.length) { panel.hidden = true; return; }

  const reference = valid[0].metrics.pairs;
  const primary = reference.map((pair) => ({ time: pair.time, value: pair.primary }));
  const lines = [{ name: currentName || currentSymbol || "主标的", color: "#00a86b", dash: "", values: primary, primary: true }];
  valid.forEach(({ series, metrics, color }) => lines.push({ name: series.name || series.symbol, color, dash: "5 3", values: metrics.pairs.map((pair) => ({ time: pair.time, value: pair.compare })), primary: false }));
  const pointsForMode = lines.map((line) => {
    const base = Number(line.values[0]?.value);
    if (!Number.isFinite(base) || base === 0) return { ...line, values: [] };
    if (comparisonMode === "return") return { ...line, values: line.values.map((point) => ({ time: point.time, value: (point.value / base - 1) * 100 })) };
    const min = Math.min(...line.values.map((point) => point.value));
    const max = Math.max(...line.values.map((point) => point.value));
    const span = max - min || Math.max(Math.abs(max) * 0.02, 1);
    return { ...line, values: line.values.map((point) => ({ time: point.time, value: (point.value - min) / span * 100 })) };
  }).filter((line) => line.values.length >= 2);
  if (!pointsForMode.length) { panel.hidden = true; return; }

  const all = pointsForMode.flatMap((line) => line.values);
  const minTime = Math.min(...all.map((point) => point.time));
  const maxTime = Math.max(...all.map((point) => point.time));
  const rawValues = all.map((point) => point.value);
  const rawMin = comparisonMode === "return" ? Math.min(0, ...rawValues) : Math.min(...rawValues);
  const rawMax = comparisonMode === "return" ? Math.max(0, ...rawValues) : Math.max(...rawValues);
  const span = rawMax - rawMin || 1;
  const width = Math.max(260, chart.parentElement?.clientWidth || 0);
  const height = 112, pad = 14;
  const xFor = (time) => pad + (maxTime === minTime ? 0 : (time - minTime) / (maxTime - minTime) * (width - pad * 2));
  const yFor = (value) => height - pad - (value - rawMin) / span * (height - pad * 2);
  const paths = pointsForMode.map((line) => {
    const points = line.values.map((point) => `${xFor(point.time).toFixed(1)},${yFor(point.value).toFixed(1)}`).join(" ");
    return `<polyline points="${points}" fill="none" stroke="${line.color}" stroke-width="${line.primary ? "2.1" : "1.7"}" stroke-dasharray="${line.dash}" stroke-linejoin="round" stroke-linecap="round" />`;
  });
  const zero = comparisonMode === "return" ? `<line class="comparison-performance-zero" x1="0" y1="${yFor(0).toFixed(1)}" x2="${width}" y2="${yFor(0).toFixed(1)}" />` : "";
  const labels = comparisonMode === "return" ? `<text class="comparison-performance-value" x="5" y="13">${rawMax.toFixed(1)}%</text><text class="comparison-performance-value" x="5" y="${height - 5}">${rawMin.toFixed(1)}%</text>` : "";
  chart.setAttribute("viewBox", `0 0 ${width} ${height}`);
  chart.innerHTML = `${zero}${labels}${paths.join("")}`;
  title.textContent = comparisonMode === "return" ? t("comparisonPerformance") : t("compareAbsolute");
  if (subtitle) subtitle.textContent = comparisonMode === "return" ? t("comparisonPerformanceHint") : t("comparisonAbsoluteHint");
  legend.innerHTML = pointsForMode.map((line) => {
    const last = line.values.at(-1)?.value;
    const detail = comparisonMode === "return" ? signedPercent(last) : formatTickerNumber(line.primary ? currentCandles.at(-1)?.close : valid.find((item) => (item.series.name || item.series.symbol) === line.name)?.metrics.lastPrice);
    const swatch = `<span aria-hidden="true" style="display:inline-block;width:8px;height:2px;margin:0 5px 2px 0;vertical-align:middle;background:${line.color}"></span>`;
    return `<span style="color:${line.color}">${swatch}${escapeHtml(line.name)} ${escapeHtml(detail)}</span>`;
  }).join("");
  panel.hidden = false;
}
