function buildKeyLevelPlan() {
  const lastPrice = Number(currentCandles[currentCandles.length - 1]?.close);
  if (!Number.isFinite(lastPrice) || lastPrice <= 0) return [];
  const levels = activeAutoLevels().filter((entry) => Number.isFinite(Number(entry.price)) && Number(entry.price) > 0);
  if (!levels.length) return [];
  const supports = levels.filter((entry) => entry.side === "support").sort((a, b) => b.price - a.price);
  const resistances = levels.filter((entry) => entry.side === "resistance").sort((a, b) => a.price - b.price);
  const support = supports.find((entry) => entry.price <= lastPrice) || supports[0];
  const resistance = resistances.find((entry) => entry.price >= lastPrice) || resistances[0];
  if (!support && !resistance) return [];
  const target = resistance && (resistances.find((entry) => entry.price > resistance.price) || resistance);
  return [
    support && { kind: "support", title: t("keyPlanSupport"), detail: t("keyPlanSupportDetail"), price: support.price, color: "success", name: t("keyPlanSupport") },
    resistance && { kind: "resistance", title: t("keyPlanResistance"), detail: t("keyPlanResistanceDetail"), price: resistance.price, color: "danger", name: t("keyPlanResistance") },
    resistance && { kind: "breakout", title: t("keyPlanBreakout"), detail: t("keyPlanBreakoutDetail"), price: resistance.price, color: "warning", name: t("keyPlanBreakout") },
    support && { kind: "stop", title: t("keyPlanStop"), detail: t("keyPlanStopDetail"), price: support.price, color: "danger", name: t("keyPlanStop") },
    target && { kind: "target", title: t("keyPlanTarget"), detail: t("keyPlanTargetDetail"), price: target.price, color: "info", name: t("keyPlanTarget") },
  ].filter(Boolean);
}
