async function searchSymbols(query) {
  const q = String(query || "").trim();
  if (!q) { closeSearchResults(); return; }
  const requestId = ++symbolSearchRequestId;
  const cached = cachedSymbolSearch(q);
  if (cached.length) {
    setSearchResults(cached, q);
    scheduleSymbolPrefetch(cached, q);
    return;
  }
  setSearchResults([], "");
  const resultsEl = document.getElementById("searchResults");
  if (resultsEl) resultsEl.innerHTML = `<div class="search-empty">${escapeHtml(t("searching"))}</div>`;
  try {
    const result = await callTool("search_symbols", { query: q, limit: 8 });
    const structured = result?.structuredContent || result || {};
    if (result?.isError || !structured.ok) throw new Error(structured.message || structured.error || "search failed");
    if (requestId !== symbolSearchRequestId) return;
    let results = mergeSearchResults(structured.results, q);
    if (!results.length) {
      const normalized = normalizeSymbolInput(q);
      if (normalized && normalized !== q.toUpperCase()) {
        const normalizedResult = await callTool("search_symbols", { query: normalized, limit: 8 });
        const normalizedData = normalizedResult?.structuredContent || normalizedResult || {};
        if (!normalizedResult?.isError && normalizedData.ok) results = mergeSearchResults(normalizedData.results, q);
      }
    }
    cacheSymbolSearch(q, results);
    setSearchResults(results, q);
    if (!results.length && structured.message && resultsEl) {
      resultsEl.innerHTML = `<div class="search-empty">${escapeHtml(structured.message)}</div>`;
    }
    scheduleSymbolPrefetch(results, q);
  } catch (error) {
    if (requestId !== symbolSearchRequestId) return;
    showError(`${t("search")}：${String(error?.message || error)}`);
    closeSearchResults();
  }
}
async function openSymbol(symbol, name, options = {}) {
  const identity = resolveSymbolIdentity(symbol, name);
  const requestedSymbol = identity.symbol || String(symbol || "").trim().toUpperCase();
  if (!requestedSymbol) return;
  if (isFtshareIntradayUnavailable(requestedSymbol, currentRangeKey)) {
    showFtshareIntradayUnavailable();
    syncTimeControls();
    return false;
  }
  const requestId = ++symbolOpenRequestId;
  const previousSymbol = String(currentSymbol || "").trim().toUpperCase();
  openingSymbol = true;
  closeSearchResults();
  setChartStatus(t("loading"));
  if (options.showLoading !== false) {
    showChartLoading(t("fetchingData"));
    showActivityNotice(t("fetchingData"));
  }
  try {
    const intraday = isIntradayRange();
    const candleRequest = candleFetchArgs(requestedSymbol);
    let fetched = options.refresh ? null : freshPrefetchedCandle(candleRequest);
    if (!fetched && !options.refresh) {
      const pending = pendingCandlePrefetch(candleRequest);
      if (pending) await pending;
      fetched = freshPrefetchedCandle(candleRequest);
    }
    const fetchedResult = fetched
      ? { structuredContent: fetched }
      : await callMarketTool("fetch_candles", candleRequest);
    fetched = fetchedResult?.structuredContent || fetchedResult || {};
    if (fetchedResult?.isError || !fetched.ok || !Array.isArray(fetched.rows)) {
      throw new Error(fetched.message || fetched.error || "fetch failed");
    }
    if (window.__DSH_KLINE_DISPOSED__ || requestId !== symbolOpenRequestId) return;
    const requestedSessions = Number(fetched.requested_sessions || fetched.requestedSessions || 0);
    const availableSessions = Number(fetched.available_sessions || fetched.availableSessions || 0);
    // Never leave the 5D control selected while the provider supplied only
    // one session. Reload the genuine 1D minute series instead of stretching
    // five-minute bars across a label that promises five days.
    if (intraday && currentRangeKey === "5d" && requestedSessions > 1 && availableSessions < requestedSessions && !options.rangeFallbackFrom) {
      currentRangeKey = "1d";
      syncTimeControls();
      return await openSymbol(requestedSymbol, name, {
        ...options,
        rangeFallbackFrom: "5D",
        showLoading: false,
      });
    }
    sourceCandles = fetched.rows.slice();
    sourceCandleInterval = String(fetched.interval || (intraday ? "minute" : currentInterval) || "day");
    localChartDataMeta = {
      source: fetched.source || "ftshare",
      source_url: fetched.source_url || fetched.sourceUrl || "",
      updated_at: fetched.updated_at || Math.floor(Date.now() / 1000),
      status: fetched.status || "delayed",
      market_status: fetched.market_status || "",
      exchange_timezone: fetched.exchange_timezone || "Asia/Shanghai",
      range_fallback: options.rangeFallbackFrom || "",
    };
    currentSymbol = fetched.symbol || requestedSymbol;
    // The local directory result carries the human-readable name. Prefer it
    // over a provider response that may only echo the symbol code.
    currentName = preferredSymbolName(identity.name, name, fetched.name, currentSymbol);
    applyMarketPalette(currentSymbol);
    const nextSymbol = String(currentSymbol || "").trim().toUpperCase();
    if (!previousSymbol || previousSymbol !== nextSymbol) {
      const remembered = workspaceTabForSymbol(nextSymbol);
      securityWorkspaceRequestId += 1;
      securityWorkspaceData = remembered?.workspace || null;
      securityWorkspaceLoading = Boolean(remembered?.workspaceLoading);
      securityIntelligenceRequestId += 1;
      securityIntelligenceData = remembered?.intelligence || null;
      securityIntelligenceLoading = Boolean(remembered?.intelligenceLoading);
      clearRangePick();
      lastMarks = [];
      lastLines = [];
    }
    await renderCurrentViewLocally({ fitToData: true });
    clearDataFetchError();
    if (requestId === symbolOpenRequestId && options.showLoading !== false) {
      finishChartLoading(t("dataReady"));
      finishActivityNotice(t("dataReady"));
    }
    scheduleLocalIndicatorWarmup();
    // Warm a genuine five-session minute series as soon as a symbol is open.
    // The request is non-blocking and cached by both the sidebar and server,
    // so a later 5D click is instant for accounts with minute-history access.
    // Unsupported/free accounts simply keep their normal daily experience: the
    // prefetch failure is swallowed inside prefetchCandleData.
    if (!intraday && !isFtshareIntradayUnsupportedSymbol(nextSymbol)) {
      window.setTimeout(() => {
        prefetchCandleData(candleFetchArgs(nextSymbol, { rangeKey: "5d" }));
      }, 0);
    }
    // The data workspace is intentionally non-blocking: K lines should be
    // visible even when a news or fundamental endpoint is slow or unavailable.
    if (!options.skipWorkspace) loadSecurityWorkspace(currentSymbol, currentName).catch(console.warn);
    // Keep the independent intelligence view scoped to the newly selected
    // symbol.  A user can search while the Board tab is open; in that case
    // waiting for another tab click would leave the previous symbol's empty
    // state on screen even though the chart itself already changed.
    if (activeSecurityTab === "sector") loadSecurityIntelligence(currentSymbol, currentName).catch(console.warn);
    return true;
  } catch (error) {
    if (window.__DSH_KLINE_DISPOSED__ || requestId !== symbolOpenRequestId) return;
    const preserve = Boolean(options.preserveOnFailure) && currentSymbol === requestedSymbol && currentCandles.length;
    const request = { symbol: requestedSymbol, name: name || currentName || requestedSymbol, rangeKey: currentRangeKey, interval: currentInterval };
    showDataFetchError(error, request);
    if (preserve) {
      updateChartDataState({}, true);
      scheduleChartDataRetry();
      setChartStatus(t("retrying"));
    }
    if (options.showLoading !== false) {
      const detail = dataFetchFailureDetail(error);
      finishChartLoading(`${t("dataFailed")}：${detail}`, true);
      finishActivityNotice(`${t("dataFailed")}：${detail}`, true);
    }
    return false;
  } finally {
    if (requestId === symbolOpenRequestId) {
      openingSymbol = false;
      setChartStatus("");
    }
  }
}

/* ---------- main tool-result handler ---------- */
async function handleToolResult(result) {
  const structured = result?.structuredContent || result || {};
  if (result?.isError || structured.error) {
    showError(structured.message || structured.error || "tool error");
    setChartStatus("失败");
    return;
  }
  showError("");

  // A data provider may send this independently from a chart payload. The view
  // deliberately consumes only this normalized contract, never provider fields.
  const workspace = structured.security_workspace || structured.securityWorkspace;
  if (workspace && typeof workspace === "object") {
    securityWorkspaceData = workspace;
    securityWorkspaceLoading = false;
    const workspaceTab = workspaceTabForSymbol(workspace.symbol || currentSymbol);
    if (workspaceTab) {
      workspaceTab.workspace = workspace;
      workspaceTab.workspaceLoading = false;
    }
    renderSecurityWorkspace();
    if (!Array.isArray(structured.chartCommands)) {
      reportSize();
      return;
    }
  }

  // draw_kline payload
  if (Array.isArray(structured.chartCommands)) {
    // A newly delivered analysis is a chart task. Existing workspace tabs keep
    // their selected page, but a new agent result should open directly to K lines.
    const incomingSymbol = String(structured.symbol || "").trim().toUpperCase();
    const existingTab = incomingSymbol ? workspaceTabs.find((tab) => tab.id === incomingSymbol) : null;
    if (!structured.local_render && structured.workspace_mode !== "launcher" && !existingTab) setSecurityTab("chart");
    if (!structured.local_render) {
      const sourceCommand = structured.chartCommands.find((command) => command.type === "SET_CANDLES" && Array.isArray(command.rows));
      if (sourceCommand?.rows?.length) sourceCandles = sourceCommand.rows.slice();
      sourceCandleInterval = String(structured.interval || sourceCandleInterval || "day");
      localChartDataMeta = structured.data_meta || structured.dataMeta || localChartDataMeta;
    }
    const previousSymbol = String(currentSymbol || "").trim().toUpperCase();
    currentSymbol = structured.symbol || currentSymbol;
    if (previousSymbol && previousSymbol !== String(currentSymbol || "").trim().toUpperCase()) {
      clearRangePick();
    }
    const identity = resolveSymbolIdentity(currentSymbol, structured.name);
    currentName = preferredSymbolName(structured.name, currentName, identity.name, currentSymbol);
    applyMarketPalette(currentSymbol);
    currentInterval = structured.interval || currentInterval;
    currentRangeKey = structured.range_key || currentRangeKey;
    updateChartDataState(structured.data_meta || structured.dataMeta || { source: "mcp", updated_at: Math.floor(Date.now() / 1000) });
    syncTimeControls();
    // Sync provider-supplied state, but never let an older local render undo a
    // more recent click. KLineCharts creates indicators asynchronously, so a
    // fast MA/VWAP toggle can otherwise arrive out of order.
    const localIndicatorVersion = Number(structured.indicator_state_version);
    const maySyncLocalIndicators = !structured.local_render
      || !Number.isFinite(localIndicatorVersion)
      || localIndicatorVersion >= indicatorStateVersion;
    // A remote draw payload only becomes the authoritative indicator stack when
    // the analysis explicitly requested indicators (indicators_explicit); an
    // implicit session keeps the calm default / the user's own toggles.
    const mayApplyRemoteIndicatorStack = structured.local_render
      || structured.indicators_explicit === true;
    if (Array.isArray(structured.indicators) && maySyncLocalIndicators && mayApplyRemoteIndicatorStack) {
      const set = new Set(structured.indicators.map(String));
      maVisible = set.has("ma");
      vwapVisible = set.has("vwap");
      volVisible = set.has("vol");
      macdVisible = set.has("macd");
      kdjVisible = set.has("kdj");
      bollVisible = set.has("boll");
      rsiVisible = set.has("rsi");
      atrVisible = set.has("atr");
      syncIndicatorConfigFromCommands(structured.chartCommands);
      syncToggleButtons();
      if (!structured.local_render) primeLocalIndicatorCache();
    }
    // Extract rows from SET_CANDLES for header
    let rows = currentCandles;
    for (const cmd of structured.chartCommands) {
      if (cmd.type === "SET_CANDLES" && Array.isArray(cmd.rows)) rows = cmd.rows;
    }
    rememberWorkspaceTab(structured);
    renderHeader(currentName, currentSymbol, rows);
    renderWatchlist();
    saveWorkspacePreferences();
    await applyChartCommands(structured);
    window.__DSH_KLINE_SAVE_VIEW__?.({ ...structured, local_render: false, indicators_explicit: false });
    // A host can send draw_kline without the optional security_workspace
    // payload. Start that non-blocking request here as well as after search so
    // News and Company do not remain blank just because this was the first
    // chart opened in a new local session.
    if (!structured.local_render && currentSymbol && !securityWorkspaceData && !securityWorkspaceLoading) {
      loadSecurityWorkspace(currentSymbol, currentName).catch(console.warn);
    }
    // A persisted 1D/5D selection requires minute candles. The first host
    // draw_kline payload is often a daily warm-up series, so replace it before
    // rendering rather than leaving a disabled day chart under an intraday tab.
    if (!structured.local_render && isIntradayRange() && sourceCandleInterval !== "minute" && currentSymbol && !openingSymbol) {
      applyIntradayPresentationDefaults();
      await openSymbol(currentSymbol, currentName);
      return;
    }
    // draw_kline intentionally accepts a wider OHLCV context so longer
    // indicators have valid warm-up data. If the host did not explicitly
    // choose a range, honour the user's persisted range immediately instead
    // of leaving a 10D/30D button active while the full source series remains
    // on screen. The nested render is local_render=true, so this is one pass
    // only and never repeats on later tool results.
    if (!structured.local_render && !structured.range_key && sourceCandles.length >= 2) {
      if (!isIntradayRange() && sourceCandleInterval === "day" && !hasLocalRowsForRange(currentRangeKey) && currentSymbol && !openingSymbol) {
        await openSymbol(currentSymbol, currentName, { preserveOnFailure: true });
        return;
      }
      await renderCurrentViewLocally({ fitToData: true });
      return;
    }
    restoreComparisons();
    refreshPercentAxis();
    setChartStatus("");
    reportSize();
    return;
  }

  // calc_range payload → cards + table
  if (structured.return_pct !== undefined && structured.bars !== undefined) {
    renderCards([
      { id: "return", title: rt("return"), value: structured.return_pct, unit: "%" },
      { id: "amp", title: rt("amplitude"), value: structured.amplitude_pct, unit: "%" },
      { id: "dd", title: rt("drawdown"), value: structured.max_drawdown?.max_drawdown_pct, unit: "%" },
      { id: "bars", title: rt("bars"), value: structured.bars, unit: "" },
      { id: "days", title: rt("days"), value: structured.duration_days, unit: viewLanguage === "zh" ? "天" : "" },
      { id: "up", title: rt("upDown"), value: `${structured.up_bars}/${structured.down_bars}`, unit: "" },
    ]);
    renderTables([{
      title: rt("detail"),
      headers: [viewLanguage === "zh" ? "字段" : "Field", viewLanguage === "zh" ? "值" : "Value"],
      rows: [
        [rt("start"), fmtDate(structured.start_time)],
        [rt("end"), fmtDate(structured.end_time)],
        [rt("openClose"), `${structured.open} / ${structured.close}`],
        [rt("highLow"), `${structured.high} / ${structured.low}`],
        [rt("streak"), `${structured.max_up_streak} / ${structured.max_down_streak}`],
        [rt("averageVolume"), structured.avg_volume],
      ],
    }]);
    revealAnalysisResults();
    setChartStatus("");
    reportSize();
    return;
  }

  // calc_metrics: show compact cards for known keys
  if (Array.isArray(structured.metrics_computed)) {
    const cards = [];
    if (structured.max_drawdown) {
      cards.push({ id: "dd", title: "最大回撤", value: structured.max_drawdown.max_drawdown_pct, unit: "%" });
    }
    if (structured.rsi?.last) {
      cards.push({ id: "rsi", title: "RSI", value: structured.rsi.last.value, unit: "" });
    }
    if (structured.atr?.last) {
      cards.push({ id: "atr", title: "ATR%", value: structured.atr.atr_pct, unit: "%" });
    }
    if (structured.ma_cross) {
      cards.push({ id: "cross", title: "交叉次数", value: (structured.ma_cross.crosses || []).length, unit: "" });
    }
    renderCards(cards);
    revealAnalysisResults();
    setChartStatus("");
    reportSize();
  }
}

