let keyLevelsRequestVersion = 0;
async function analyzeKeyLevels() {
  if (!currentSymbol || currentCandles.length < 5) {
    setChartStatus(t("keyLevelsInsufficient"));
    return;
  }
  const version = ++keyLevelsRequestVersion;
  const rows = currentCandles;
  const symbol = currentSymbol;
  const interval = currentInterval;
  const range = currentRangeKey;
  const adjust = currentAdjust;
  const isCurrent = () => !window.__DSH_KLINE_DISPOSED__ && version === keyLevelsRequestVersion
    && rows === currentCandles && symbol === currentSymbol && interval === currentInterval
    && range === currentRangeKey && adjust === currentAdjust;
  const button = document.getElementById("keyLevelsBtn");
  if (button) button.disabled = true;
  setChartStatus(t("keyLevelsLoading"));
  showActivityNotice(t("keyLevelsLoading"));
  try {
    const result = await callMarketTool("analyze_key_levels", { symbol, rows }, 1);
    if (!isCurrent()) return;
    // Only update annotations. Keep source bars, adjustment, indicators and zoom.
    syncAutoLevelsFromPayload(result);
    const noLevels = (result.structuredContent || result).status === "no_levels";
    if (noLevels) {
      const message = t("keyLevelsEmpty");
      setChartStatus(message);
      finishActivityNotice(message);
    } else {
      // The reference cards are the completion feedback. Do not cover the
      // quote in the upper-right header with a duplicate floating notice.
      setChartStatus("");
      dismissActivityNotice();
    }
  } catch (error) {
    if (!isCurrent()) return;
    console.warn("key-level analysis", error);
    setChartStatus(t("keyLevelsLocalFailed"));
    finishActivityNotice(t("keyLevelsLocalFailed"), true);
  } finally {
    if (!window.__DSH_KLINE_DISPOSED__ && !isCurrent()) {
      if (document.getElementById("activityNoticeText")?.textContent === t("keyLevelsLoading")) finishActivityNotice(t("keyLevelsCancelled"));
      if (document.getElementById("chartStatus")?.textContent === t("keyLevelsLoading")) setChartStatus(t("keyLevelsCancelled"));
    }
    if (button) button.disabled = false;
  }
}
async function submitRangeAnalyze() {
  if (!rangePickStart || !rangePickEnd || !currentCandles.length) return;
  setChartStatus(rt("calculating"));
  try {
    const res = await callTool("calc_range", {
      rows: currentCandles,
      start_time: rangePickStart.time,
      end_time: rangePickEnd.time,
    });
    await handleToolResult(res);
    setChartStatus("");
  } catch (e) {
    showError(`${rt("failed")}：${String(e)}`);
    setChartStatus("失败");
  }
}

/* ---------- indicator toggle → reapply in the current view ---------- */
async function redrawWithIndicators() {
  // Host-provided local renders may populate currentCandles without retaining
  // a separate sourceCandles buffer. Indicator toggles must still redraw that
  // already-visible chart.
  if (!sourceCandles.length && !currentCandles.length) return;
  if (redrawing) {
    indicatorRedrawPending = true;
    return;
  }
  redrawing = true;
  setChartStatus(rt("updating"));
  try {
    do {
      indicatorRedrawPending = false;
      const renderVersion = indicatorStateVersion;
      await renderCurrentViewLocally();
      // Allow KLineCharts' queued indicator creation to settle before deciding
      // whether a later click requires another pass.
      await new Promise((resolve) => window.requestAnimationFrame(resolve));
      if (renderVersion !== indicatorStateVersion) indicatorRedrawPending = true;
    } while (indicatorRedrawPending);
  } catch (e) {
    console.warn("redraw", e);
    showError(`${rt("redrawFailed")}：${String(e)}`);
  } finally {
    redrawing = false;
    setChartStatus("");
  }
}
function wireToggle(btnId, getter, setter) {
  const button = document.getElementById(btnId);
  if (!button) return;
  button.onclick = () => {
    const name = btnId.replace(/Btn$/, "");
    indicatorStateVersion += 1;
    setter(!getter());
    saveWorkspacePreferences();
    syncToggleButtons();
    recalcChartHeight();
    redrawWithIndicators().then(() => {
      if (getter()) focusIndicatorPane(name);
    }).catch(console.warn);
  };
}

